CREATE TABLE IF NOT EXISTS relay_meta (id INTEGER PRIMARY KEY CHECK(id=1), version INTEGER NOT NULL);
INSERT OR IGNORE INTO relay_meta VALUES(1,1);
CREATE TABLE IF NOT EXISTS relay_jobs (id TEXT PRIMARY KEY, account TEXT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE, node TEXT NOT NULL REFERENCES nodes(id) ON DELETE CASCADE, binding TEXT NOT NULL, digest TEXT NOT NULL, state TEXT NOT NULL, deadline INTEGER NOT NULL, result_digest TEXT, permit_issued INTEGER);
CREATE INDEX IF NOT EXISTS relay_admission ON relay_jobs(account,state);
CREATE TABLE IF NOT EXISTS relay_frames (job TEXT NOT NULL REFERENCES relay_jobs(id) ON DELETE CASCADE, sequence INTEGER NOT NULL, digest TEXT NOT NULL, bytes INTEGER NOT NULL, PRIMARY KEY(job,sequence));
